def conv2d_same(x: np.ndarray, w: np.ndarray, b: np.ndarray) -> np.ndarray:
    B, C, H, W = x.shape
    out_c, in_c, kh, kw = w.shape
    x_pad = np.pad(x, ((0, 0), (0, 0), (1, 1), (1, 1)), mode='constant')
    out = np.zeros((B, out_c, H, W))
    for r in range(H):
        for c in range(W):
            patch = x_pad[:, :, r:r+3, c:c+3]
            for oc in range(out_c):
                out[:, oc, r, c] = np.sum(patch * w[oc], axis=(1, 2, 3)) + b[oc]
